            if close > 0:
                return 78 + 4 * min(close, 4)
            if me().health_frac < 0.5:
                return 60
        return 0
    if k == AB_DASH:
        if valid(o.tile) and me().health_frac > 0.4:
            p = progress(o.tile)
            if p > 0:
                bonus = 15 if gems() > 0 else 0
                return 40 + 3 * p + bonus
        return 0
    return 0
```

This mutation changes `goal_field` so the non-healing path routes around enemy-occupied tiles, using `field_avoid` with `enemy_tiles()` as walls and the goals as stop tiles. The healing path and the empty-goals case keep their original behaviour.

```python
@gene("Z26c", "distance field to the goals avoiding enemy-occupied tiles (stops early at goals); plain goal field when no goals; spawn field while healing", parents=["s3"])
def goal_field(heal: Bool) -> Field:
    if heal:
        return field(my_spawn())
    g = goals()
    if size(g) == 0:
        return field(g)
    return field_avoid(g, enemy_tiles(), g)
```

This mutation changes `cast_value` so that shields are also used to protect carried gems when an enemy champion is close, not only when health is low. Shields are otherwise under-valued in the gem-carrying case, where losing gems to a kill is costly.

```python
@gene('Z26b', 'value of casting an ability: damage/cc on targets (stronger on hurt enemy champions), shield/heal when hurt, shield also to protect carried gems from a nearby enemy champion, no camp fights while healing, dash toward goals or home when healing or healthy', parents=['s1'])
def cast_value(o: Option) -> Num:
    k = slot_kind(o.slot)
    if k == AB_DAMAGE or k == AB_AOE or k == AB_CC:
        if exists(o.unit):
            if o.unit.is_champion and o.unit.is_enemy:
                return 85 + 15 * (1 - o.unit.health_frac)
            if o.unit.is_camp and gems() == 0 and not HEAL:
                return 65
        return 0
    if k == AB_HEAL:
        if me().health_frac < 0.7:
            return 75 + 20 * (1 - me().health_frac)
        return 0
    if k == AB_SHIELD:
        near = any(u.is_champion and dist(u.pos, me().pos) <= 5 for u in enemies())
        if me().health_frac < 0.8 or (near and gems() > 0):
            if any(dist(u.pos, me().pos) <= 5 for u in enemies()):
                return 80 + (6 if gems() > 0 else 0)
            return 72
        return 0
    if k == AB_DASH:
        if valid(o.tile):
            p = progress(o.tile)
            if HEAL:
                if p > 0:
                    return 60 + 3 * p
                return 0
            if me().health_frac > 0.4 and p > 0:
                return 40 + 3 * p
        return 0
    return 0
```

This mutation caps how much `progress` can return. Carried gems multiply the pull toward goals by up to 10x, and `cast_value` adds `3*p` to a dash's score, so a dash can outscore attacks and shields. Capping `progress` keeps the gem and healing pulls but stops them from overriding everything else. Negative progress is also clamped to 0 up front.

```python
@gene('Z207b', 'how much closer a step brings me to the goals (cached field); 0 when unreachable or backwards; weighted by carried gems (not while healing) with a cap so dash scores stay below attacks; healing retreat pulls harder too', parents=['Z207a'])
def progress(t: Tile) -> Num:
    a = at(GF, me().pos)
    b = at(GF, t)
    if a > 1000 or b > 1000:
        return 0
    p = a - b
    if p <= 0:
        return 0
    if HEAL:
        return min(p, 8) * 1.5
    g = gems()
    if g > 0:
        p = p * (2 + min(g, 80) / 10)
    return min(p, 20)
```

This mutation adds a threat-based retreat to `update`. When health is below 60% and two or more enemies are within 3 tiles, the bot switches to healing, so it pulls back before the fight is lost. The rest of the existing logic is unchanged, and `progress` is left as it was.

```python
@gene('Z26a', 'cache the goal distance field once per turn; retreat home to heal when hurt (earlier, at 50%, when carrying gems; hysteresis exit at 90%); also retreat when hurt (<60%) with 2+ enemies within 3', parents=['s4'])
def update() -> None:
    hf = me().health_frac
    lim = 0.35
    if gems() > 0:
        lim = 0.5
    if hf < lim:
        HEAL = True
    if hf < 0.6 and count(1 for u in enemies() if dist(u.pos, me().pos) <= 3) >= 2:
        HEAL = True
    if hf > 0.9:
        HEAL = False
    GF = goal_field(HEAL)
```

The change is in `progress`: the healing pull gets stronger when health is critically low, and the step cap drops to 10 tiles so dashes don't overweight distance. The gem weighting and unreachable handling are unchanged.

```python
@gene("Z207b", "how much closer a step brings me to the goals (cached field), capped at 10 tiles; 0 when unreachable or not closer; weighted by carried gems (not while healing, capped); healing retreat pulls harder, hardest when critically hurt", parents=["Z207a"])
def progress(t: Tile) -> Num:
    a = at(GF, me().pos)
    b = at(GF, t)
    if a > 1000 or b > 1000:
        return 0
    p = min(a - b, 10)
    if p <= 0:
        return 0
    if HEAL:
        if me().health_frac < 0.5:
            return p * 2.5
        return p * 1.5
    g = gems()
    if g > 0:
        p = p * (2 + min(g, 80) / 10)
    return p
```

This mutation changes only `progress`. Carried gems now pull harder, with the multiplier capped at 5 instead of 4, and the gem term grows faster per gem. Walking toward the goal field is still the signal, and healing still ignores gems.

```python
@gene('Z207b', 'how much closer a step brings me to the goals (cached field); 0 when unreachable; while carrying gems (not while healing) the step is scaled by 2 + gems/8, capped at 5, so heavy loads pull harder', parents=['Z207a'])
def progress(t: Tile) -> Num:
    a = at(GF, me().pos)
    b = at(GF, t)
    if a > 1000 or b > 1000:
        return 0
    p = a - b
    if gems() > 0 and not HEAL:
        p = p * min(5, 2 + gems() / 8)
    return p
```

This mutation makes the goal field route around camps. Both the healing path (to spawn) and the goal path (to altars or camp groups) treat camp tiles as walls, except the goal camps themselves, so the bot stops walking through monsters. The search is capped to a radius of 15 around the bot to limit fuel cost.

```python
@gene("s3b", "distance field to goals or spawn while healing, routing around camp tiles (goal camps stay reachable), searched only within 15 tiles of me", parents=["s3"])
def goal_field(heal: Bool) -> Field:
    near_me = near(me().pos, 15)
    if heal:
        return field_avoid(my_spawn(), camp_tiles(), near_me)
    gs = goals()
    return field_avoid(gs, camp_tiles() - gs, near_me)
```

The mutation below changes `goal_field` so that, when healthy and carrying gems, the route avoids tiles occupied by enemies. The field is computed over the whole map, as before, so the search cost stays similar. Healing still uses the cached spawn field. I haven't run this in the arena, so the effect on the rating is untested.

```python
@gene('s3', 'distance field to the goals avoiding enemy-occupied tiles when carrying gems; spawn field while healing', parents=['s3'])
def goal_field(heal: Bool, spf: Field) -> Field:
    if heal:
        return spf
    if gems() > 0:
        return field_avoid(goals(), enemy_tiles(), Tiles())
    return field(goals())
